<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\UserProfileNicknameVO;

trait UserProfileNicknameAttributeHolder
{
    protected UserProfileNicknameVO|string|null $nickname = null;
    protected bool $nicknameAssigned = false;

    public function getNicknameOrCurrent(?UserProfileNicknameVO $nickname): ?UserProfileNicknameVO
    {
        return $this->nicknameAssigned ? ($this->nickname === null ? null : UserProfileNicknameVO::from($this->nickname)) : $nickname;
    }
    public function nicknameTryBuildInitial(ConstraintFailList $error): ?UserProfileNicknameVO
    {
        return  UserProfileNicknameVO::tryFrom($this->nicknameAssigned ? $this->nickname : null, $error);
    }
    public function nickname(UserProfileNicknameVO|string|null $nickname): static
    {
        $this->nickname = $nickname;
        $this->nicknameAssigned = true;
        return $this;
    }
    public function getNickname(): ?string
    {
        return $this->nickname instanceof UserProfileNicknameVO ? $this->nickname->value() : $this->nickname;
    }
    public function isNicknameAssigned(): bool
    {
        return $this->nicknameAssigned;
    }
    public function writeNicknameTo(mixed $att): void
    {
        if ($this->nicknameAssigned) {
            $att->nickname($this->nickname);
        }
    }
    public function readNicknameFrom(mixed $att): void
    {
        if ($att->isNicknameAssigned()) {
            $nickname = $att->getNickname();
            $this->nickname($nickname);
        }
    }
    public function unsetNickname(): static
    {
        $this->nicknameAssigned = false;
        return $this;
    }
    protected function withDefaultNickname(): void
    {
    }
    protected function withAssertedNicknameRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->nicknameAssigned = $this->nicknameAssigned) {
            $value->nickname = UserProfileNicknameVO::tryFrom($this->nickname, $errorsList);
        }
    }
}
